let newsSwiper=new Swiper(".article-recommended-swiper",{slidesPerView:1,spaceBetween:12,navigation:{nextEl:".article-recommended-swiper .swiper-pagination__wrapper"},scrollbar:{el:".article-recommended-swiper .swiper-scrollbar",draggable:!0,snapOnRelease:!0},breakpoints:{1050:{slidesPerView:"4"},800:{slidesPerView:"3"},600:{slidesPerView:"2"}}}),fixArticleRecommendedSwiper=()=>{var e=document.querySelector(".article-section .container").getBoundingClientRect(),i=document.querySelector(".article-recommended-swiper.swiper"),e=e.width-40+"px";i.style.width=e};window.addEventListener("resize",fixArticleRecommendedSwiper),fixArticleRecommendedSwiper();